inputs = ['fbzb', 'ckbjb', 'kfxz', 'va', 'hawgjb']
outputs = ['fbhayb', 'ckbjb', 'kfxhay', 'va', 'kzahujeb']

print("Input strings:", inputs)
print("Output strings:", outputs)
print()

# Let's manually compare each pair to see what changes
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        print(f"  Difference found!")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  First difference at position {j}: '{inp[j]}' -> '{outp[j]}'")
                break
        else:
            if len(inp) != len(outp):
                print(f"  Length difference: {len(inp)} -> {len(outp)}")
    else:
        print(f"  No difference")
    print()

